"use client"; 
import Link from "next/link";
import { useState } from "react";

const Header = () => {
  const [value, setValue] = useState("");
  return (
    <div className="bg-blue-900 py-6 relative">
      <div className="container mx-auto flex justify-between">
        <span className="text-white text-3xl font-bold">Booking</span>
        <span className="hidden lg:flex justify-between gap-3">
          <Link href="/" className="flex items-center hover:bg-white/10 hover:rounded-full px-4 font-bold text-white">Home</Link>
          <Link href="/hotels" className="flex items-center hover:bg-white/10 hover:rounded-full px-4 font-bold text-white">Hotels</Link>
          <Link href="/experience" className="flex items-center hover:bg-white/10 hover:rounded-full px-4 font-bold text-white">Experience</Link>
          <Link href="/about" className="flex items-center hover:bg-white/10 hover:rounded-full px-4 font-bold text-white">About</Link>
          <Link href={"/dashboard"} className="flex items-center hover:bg-white mr-8 hover:text-blue-900  px-4 font-bold text-white border border-white rounded-full">Dashboard</Link>
          <Link href="/login" className="flex items-center rounded-md bg-white px-4 font-bold text-blue-900">Login</Link>
          <Link href="/register" className="flex items-center rounded-md bg-white px-4 font-bold text-blue-900">Register</Link>
        </span>

      </div>

      <div className="absolute top-27 left-1/2 transform -translate-x-1/2 -translate-y-1/2 container mx-auto ">
        <form className='bg-white border-2 border-orange-400 text-gray-500 rounded-lg px-6 py-2 flex flex-col md:flex-row max-md:items-start gap-4 max-md:mx-auto'>

        <div>
          <div className='flex items-center gap-2'>
            <svg className="w-4 h-4 text-gray-800" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="none" viewBox="0 0 24 24" >
              <path stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 10h16M8 14h8m-4-7V4M7 7V4m10 3V4M5 20h14a1 1 0 0 0 1-1V7a1 1 0 0 0-1-1H5a1 1 0 0 0-1 1v12a1 1 0 0 0 1 1Z" />
            </svg>
            <label htmlFor="destinationInput">Destination</label>
          </div>
          <input list='destinations' id="destinationInput" type="text" className=" rounded border border-gray-200 px-3 py-1.5 mt-1.5 text-sm outline-none" placeholder="Type here" required />
        </div>

        <div>
          <div className='flex items-center gap-2'>
            <svg className="w-4 h-4 text-gray-800" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="none" viewBox="0 0 24 24" >
              <path stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 10h16M8 14h8m-4-7V4M7 7V4m10 3V4M5 20h14a1 1 0 0 0 1-1V7a1 1 0 0 0-1-1H5a1 1 0 0 0-1 1v12a1 1 0 0 0 1 1Z" />
            </svg>
            <label htmlFor="checkIn">Check in</label>
          </div>
          <input
      id="checkIn"
      type={value ? "date" : "text"}   // 👈 text হলে placeholder কাজ করবে
      placeholder="Check-in date"
      value={value}
      onChange={(e) => setValue(e.target.value)}
      className="rounded border border-gray-200 px-3 py-1.5 mt-1.5 text-sm outline-none"
    />
        </div>

        <div>
          <div className='flex items-center gap-2'>
            <svg className="w-4 h-4 text-gray-800" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="none" viewBox="0 0 24 24" >
              <path stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 10h16M8 14h8m-4-7V4M7 7V4m10 3V4M5 20h14a1 1 0 0 0 1-1V7a1 1 0 0 0-1-1H5a1 1 0 0 0-1 1v12a1 1 0 0 0 1 1Z" />
            </svg>
            <label htmlFor="checkOut">Check out</label>
          </div>
          <input id="checkOut" type="date" className=" rounded border border-gray-200 px-3 py-1.5 mt-1.5 text-sm outline-none" />
        </div>

        <div className='flex md:flex-col max-md:gap-2 max-md:items-center'>
          <label htmlFor="guests">Guests</label>
          <input min={1} max={4} id="guests" type="number" className=" rounded border border-gray-200 px-3 py-1.5 mt-1.5 text-sm outline-none  max-w-16" placeholder="0" />
        </div>

        <button className='flex items-center justify-center gap-1 rounded-md bg-black py-3 px-4 text-white my-auto cursor-pointer max-md:w-full max-md:py-1' >
          <svg className="w-4 h-4 text-white" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="none" viewBox="0 0 24 24" >
            <path stroke="currentColor" strokeLinecap="round" strokeWidth="2" d="m21 21-3.5-3.5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Z" />
          </svg>
          <span>Search</span>
        </button>
      </form>
      </div>
    </div>
  );
}

export default Header;
